BEGIN;
SET ROLE air_repository_owner;
CREATE SCHEMA gate6_3_backup_20261019_124010 AUTHORIZATION air_repository_owner;
CREATE TABLE gate6_3_backup_20261019_124010.course_current_catalog_api AS TABLE reporting.course_current_catalog_api;
CREATE TABLE gate6_3_backup_20261019_124010.course_catalog_detail_api AS TABLE reporting.course_catalog_detail_api;
CREATE TABLE reporting.course_organization_reconciliation (
 university_course_id text PRIMARY KEY,
 validated_course_code text NOT NULL,
 ww_acad_org text,
 source_department_name text,
 department_name text,
 reconciliation_status text NOT NULL,
 source_file_name text NOT NULL,
 source_sha256 text NOT NULL,
 source_row_number bigint,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK (source_sha256='2B4B77F3D00BC18EDEECFA5C6342B2E22A67699886FC60B94325908517F270AD'),
 CHECK (reconciliation_status IN ('EXACT_ID_CODE_DEPARTMENT','EXACT_ID_CODE_BLANK','CODE_MISMATCH_DEPARTMENT_HOLD','CODE_MISMATCH_BLANK_HOLD','UNMATCHED_SOURCE','CONTROLLED_TEST')),
 CHECK ((reconciliation_status='EXACT_ID_CODE_DEPARTMENT' AND department_name IS NOT NULL AND btrim(department_name)<>'') OR (reconciliation_status<>'EXACT_ID_CODE_DEPARTMENT' AND department_name IS NULL))
);
ALTER TABLE reporting.course_current_catalog_api ADD COLUMN college_name text;
ALTER TABLE reporting.course_current_catalog_api ADD COLUMN department_name text;
ALTER TABLE reporting.course_catalog_detail_api ADD COLUMN department_name text;
DELETE FROM reporting.course_current_catalog_api;
DELETE FROM reporting.course_catalog_detail_api;
DO $$
BEGIN
 IF (SELECT count(*) FROM reporting.course_organization_reconciliation)<>966 THEN RAISE EXCEPTION 'reconciliation count failed'; END IF;
 IF (SELECT count(*) FROM reporting.course_organization_reconciliation WHERE department_name IS NOT NULL)<>827 THEN RAISE EXCEPTION 'department count failed'; END IF;
 IF (SELECT count(*) FROM reporting.course_current_catalog_api)<>966 THEN RAISE EXCEPTION 'catalog API count failed'; END IF;
 IF (SELECT count(*) FROM reporting.course_current_catalog_api WHERE college_name IS NOT NULL)<>964 THEN RAISE EXCEPTION 'college count failed'; END IF;
 IF (SELECT count(*) FROM reporting.course_current_catalog_api WHERE department_name IS NOT NULL)<>827 THEN RAISE EXCEPTION 'catalog department count failed'; END IF;
 IF (SELECT count(*) FROM reporting.course_catalog_detail_api)<>964 THEN RAISE EXCEPTION 'detail API count failed'; END IF;
 IF (SELECT count(*) FROM reporting.course_catalog_detail_api WHERE department_name IS NOT NULL)<>827 THEN RAISE EXCEPTION 'detail department count failed'; END IF;
END
$$;
ANALYZE reporting.course_organization_reconciliation;
ANALYZE reporting.course_current_catalog_api;
ANALYZE reporting.course_catalog_detail_api;
COMMIT;
